const _testdata = "testdata"

func TestGrail_AllServices(t *testing.T) {
	// The simplified_query_result.json is a simplified version of the actual query result from
	// Grail (where only the first 10 results are kept). It can be generated by authenticating to
	// Grail, then POSTing query_all.txt to its /yql endpoint and keeping only the first 10 result
	// entries.
	//
	// The expected output file can be generated via the following command:
	// cat src/github.com/uber-research/rpcshield/go/grail/testdata/simplified_query_result.json | jq ".result | .[:10]" > src/github.com/uber-research/rpcshield/go/grail/testdata/simplified_query_result.expected.output.json
	callCount := 0
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		require.Equal(t, r.Method, http.MethodPost, "Test HTTP server only supports POST method, got %q", r.Method)

		var data []byte
		var err error
		if callCount == 0 {
			// First call is for AllServices
			data, err = os.ReadFile(filepath.Join(_testdata, "simplified_query_result.json"))
			require.NoError(t, err)
		} else {
			// Second call is for namespace/burst_strategy enrichment - return empty result
			data = []byte(`{"result": []}`)
		}
		callCount++

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, err = w.Write(data)
		require.NoError(t, err)
	}))
	defer ts.Close()

	grail, err := New(&Options{Host: ts.URL, USSOToken: "xxxx"})
	require.NoError(t, err)
	services, err := grail.AllServices(context.Background())
	require.NoError(t, err)

	var expectedServices []Service
	f, err := os.Open(filepath.Join(_testdata, "simplified_query_result.expected.output.json"))
	require.NoError(t, err)
	err = json.NewDecoder(f).Decode(&expectedServices)
	require.NoError(t, err)

	require.Equal(t, expectedServices, services)
}

