func TestGrail_Error(t *testing.T) {
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusInternalServerError)
	}))
	defer ts.Close()

	grail, err := New(&Options{Host: ts.URL, USSOToken: "xxxx", GitURI: GoCodeGitURI})
	require.NoError(t, err)

	t.Run("AllServices", func(t *testing.T) {
		// Note: AllServices now fails on the first request (services query),
		// so it won't reach the namespace/burst_strategy query
		_, err := grail.AllServices(context.Background())
		require.ErrorContains(t, err, "grail")
	})

	t.Run("AllActiveGoServices", func(t *testing.T) {
		t.Parallel()

		_, err := grail.AllActiveGoServices(context.Background())
		require.ErrorContains(t, err, "grail request")
	})

	t.Run("AllNetworkGroups", func(t *testing.T) {
		t.Parallel()

		_, err := grail.AllNetworkGroups(context.Background())
		require.ErrorContains(t, err, "grail request")
	})
}

// TestGrail_NoUSSToken verifies that New returns an error when the USSO token
// is not provided in the options, ensuring proper authentication configuration.
func TestGrail_NoUSSToken(t *testing.T) {
	t.Parallel()

	_, err := New(&Options{Host: "https://example.com"})
	require.ErrorContains(t, err, "USSO")
}

// TestGrail_NoHost verifies that New returns an error when the host is not
// provided in the options, since there is no generic default to fall back to.
func TestGrail_NoHost(t *testing.T) {
	t.Parallel()

	_, err := New(&Options{USSOToken: "xxxx"})
	require.ErrorContains(t, err, "host")
}

// TestGrail_ErrorDecode verifies that the Grail client properly handles and
// reports decode errors when the server responds with invalid JSON data.
func TestGrail_ErrorDecode(t *testing.T) {
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Respond with OK but with invalid JSON data to trigger decode error.
		// This will fail on the first request (AllServices query)
		w.WriteHeader(http.StatusOK)
		_, err := w.Write([]byte("invalid json"))
		require.NoError(t, err)
	}))
	defer ts.Close()

	grail, err := New(&Options{Host: ts.URL, USSOToken: "xxxx"})
	require.NoError(t, err)
	_, err = grail.AllServices(context.Background())
	require.ErrorContains(t, err, "decode")
}

func TestGrail_enrichWithNamespaceBurstStrategy(t *testing.T) {
	tests := []struct {
		name              string
		namespaceResponse string
		inputServices     []Service
		expectedServices  []Service
		expectError       bool
	}{
		{
			name: "single service with overcommit and all break-before-make",
			namespaceResponse: `{"result": [
				{
					"service_name": "test-service",
					"environment_name": "production",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_BREAK_BEFORE_MAKE"
				},
				{
					"service_name": "test-service",
					"environment_name": "prod-staging",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_BREAK_BEFORE_MAKE"
				}
			]}`,
			inputServices: []Service{
				{Name: "test-service", Tier: 1, GitURI: "gitolite@example.internal:go-code"},
			},
			expectedServices: []Service{
				{Name: "test-service", Tier: 1, GitURI: "gitolite@example.internal:go-code", HasOvercommit: true, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_ALL_ENVIRONMENTS", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_NO_ENVIRONMENT"},
			},
			expectError: false,
		},
		{
			name: "service with mixed strategies - some environments with different strategies",
			namespaceResponse: `{"result": [
				{
					"service_name": "mixed-service",
					"environment_name": "production",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_BREAK_BEFORE_MAKE"
				},
				{
					"service_name": "mixed-service",
					"environment_name": "prod-staging",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_MAKE_BEFORE_BREAK"
				},
				{
					"service_name": "mixed-service",
					"environment_name": "prod-canary",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_BREAK_BEFORE_MAKE"
				}
			]}`,
			inputServices: []Service{
				{Name: "mixed-service", Tier: 2, GitURI: "gitolite@example.internal:go-code"},
			},
			expectedServices: []Service{
				{Name: "mixed-service", Tier: 2, GitURI: "gitolite@example.internal:go-code", HasOvercommit: true, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_SOME_ENVIRONMENTS", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_SOME_ENVIRONMENTS"},
			},
			expectError: false,
		},
		{
			name:              "service with no environments in namespace data",
			namespaceResponse: `{"result": []}`,
			inputServices: []Service{
				{Name: "no-env-service", Tier: 3, GitURI: "gitolite@example.internal:go-code"},
			},
			expectedServices: []Service{
				{Name: "no-env-service", Tier: 3, GitURI: "gitolite@example.internal:go-code", HasOvercommit: false, BreakBeforeMakeBurstStrategy: "", MakeBeforeBreakBurstStrategy: ""},
			},
			expectError: false,
		},
		{
			name: "multiple services with different configurations",
			namespaceResponse: `{"result": [
				{
					"service_name": "service-a",
					"environment_name": "production",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_MAKE_BEFORE_BREAK"
				},
				{
					"service_name": "service-b",
					"environment_name": "production",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_DEFAULT"
				},
				{
					"service_name": "service-b",
					"environment_name": "prod-staging",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_MAKE_BEFORE_BREAK"
				}
			]}`,
			inputServices: []Service{
				{Name: "service-a", Tier: 1, GitURI: "gitolite@example.internal:go-code"},
				{Name: "service-b", Tier: 2, GitURI: "gitolite@example.internal:go-code"},
				{Name: "service-c", Tier: 3, GitURI: "gitolite@example.internal:go-code"}, // No data in namespace response
			},
			expectedServices: []Service{
				{Name: "service-a", Tier: 1, GitURI: "gitolite@example.internal:go-code", HasOvercommit: true, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_NO_ENVIRONMENT", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_ALL_ENVIRONMENTS"},
				{Name: "service-b", Tier: 2, GitURI: "gitolite@example.internal:go-code", HasOvercommit: true, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_SOME_ENVIRONMENTS", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_SOME_ENVIRONMENTS"},
				{Name: "service-c", Tier: 3, GitURI: "gitolite@example.internal:go-code", HasOvercommit: false, BreakBeforeMakeBurstStrategy: "", MakeBeforeBreakBurstStrategy: ""},
			},
			expectError: false,
		},
		{
			name: "invalid burst strategy value defaults to break-before-make",
			namespaceResponse: `{"result": [
				{
					"service_name": "invalid-strategy",
					"environment_name": "production",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_INVALID"
				}
			]}`,
			inputServices: []Service{
				{Name: "invalid-strategy", Tier: 1, GitURI: "gitolite@example.internal:go-code"},
			},
			expectedServices: []Service{
				{Name: "invalid-strategy", Tier: 1, GitURI: "gitolite@example.internal:go-code", HasOvercommit: true, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_ALL_ENVIRONMENTS", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_NO_ENVIRONMENT"},
			},
			expectError: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			callCount := 0
			ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				require.Equal(t, http.MethodPost, r.Method)
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(http.StatusOK)

				if callCount == 0 {
					// Return the namespace response
					_, err := w.Write([]byte(tt.namespaceResponse))
					require.NoError(t, err)
				}
				callCount++
			}))
			defer ts.Close()

			grail, err := New(&Options{Host: ts.URL, USSOToken: "xxxx"})
			require.NoError(t, err)

			result, err := grail.enrichWithNamespaceBurstStrategy(context.Background(), tt.inputServices)
			if tt.expectError {
				require.Error(t, err)
				return
			}

			require.NoError(t, err)
			require.Equal(t, tt.expectedServices, result)
		})
	}
}

func TestCountServicesWithFlag(t *testing.T) {
	services := []Service{
		{Name: "service-a", Tier: 1, HasOvercommit: true, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_ALL_ENVIRONMENTS", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_NO_ENVIRONMENT"},
		{Name: "service-b", Tier: 2, HasOvercommit: true, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_SOME_ENVIRONMENTS", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_SOME_ENVIRONMENTS"},
		{Name: "service-c", Tier: 3, HasOvercommit: true, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_NO_ENVIRONMENT", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_ALL_ENVIRONMENTS"},
		{Name: "service-d", Tier: 4, HasOvercommit: false, BreakBeforeMakeBurstStrategy: "", MakeBeforeBreakBurstStrategy: ""},
	}

	tests := []struct {
		name          string
		predicate     func(Service) bool
		expectedCount int
	}{
		{
			name:          "count services with overcommit",
			predicate:     func(s Service) bool { return s.HasOvercommit },
			expectedCount: 3, // service-a, service-b, and service-c
		},
		{
			name:          "count services without overcommit",
			predicate:     func(s Service) bool { return !s.HasOvercommit },
			expectedCount: 1, // service-d
		},
		{
			name: "count services with break-before-make all environments",
			predicate: func(s Service) bool {
				return s.BreakBeforeMakeBurstStrategy == "BURST_STRATEGY_BREAK_BEFORE_MAKE_ALL_ENVIRONMENTS"
			},
			expectedCount: 1, // service-a
		},
		{
			name: "count services with make-before-break all environments",
			predicate: func(s Service) bool {
				return s.MakeBeforeBreakBurstStrategy == "BURST_STRATEGY_MAKE_BEFORE_BREAK_ALL_ENVIRONMENTS"
			},
			expectedCount: 1, // service-c
		},
		{
			name: "count services with some environments burst strategy",
			predicate: func(s Service) bool {
				return s.BreakBeforeMakeBurstStrategy == "BURST_STRATEGY_BREAK_BEFORE_MAKE_SOME_ENVIRONMENTS" ||
					s.MakeBeforeBreakBurstStrategy == "BURST_STRATEGY_MAKE_BEFORE_BREAK_SOME_ENVIRONMENTS"
			},
			expectedCount: 1, // service-b
		},
		{
			name:          "count services with high tier",
			predicate:     func(s Service) bool { return s.Tier >= 3 },
			expectedCount: 2, // service-c and service-d
		},
		{
			name: "count services with empty burst strategy fields",
			predicate: func(s Service) bool {
				return s.BreakBeforeMakeBurstStrategy == "" && s.MakeBeforeBreakBurstStrategy == ""
			},
			expectedCount: 1, // service-d
		},
		{
			name:          "count all services",
			predicate:     func(s Service) bool { return true },
			expectedCount: 4, // all services
		},
		{
			name:          "count no services",
			predicate:     func(s Service) bool { return false },
			expectedCount: 0, // no services
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := countServicesWithFlag(services, tt.predicate)
			require.Equal(t, tt.expectedCount, result)
		})
	}

	// Test with empty services slice
	t.Run("empty services slice", func(t *testing.T) {
		result := countServicesWithFlag([]Service{}, func(s Service) bool { return true })
		require.Equal(t, 0, result)
	})

	// Test with nil predicate should panic (testing defensive behavior)
	t.Run("nil predicate panics", func(t *testing.T) {
		require.Panics(t, func() {
			countServicesWithFlag(services, nil)
		})
	})
}

func TestGrail_AllServices_WithEnrichment(t *testing.T) {
	tests := []struct {
		name                 string
		servicesResponse     string
		namespaceResponse    string
		expectedServices     []Service
		expectNamespaceError bool
	}{
		{
			name: "successful enrichment with overcommit and break-before-make",
			servicesResponse: `{"result": [
				{"name": "service-a", "tier": 1, "git_uri": "gitolite@example.internal:go-code"},
				{"name": "service-b", "tier": 2, "git_uri": "gitolite@example.internal:go-code"}
			]}`,
			namespaceResponse: `{"result": [
				{
					"service_name": "service-a",
					"environment_name": "production",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_BREAK_BEFORE_MAKE"
				},
				{
					"service_name": "service-a",
					"environment_name": "staging",
					"environment_type": "ENVIRONMENT_TYPE_STAGING",
					"namespace": "default",
					"burst_strategy": "BURST_STRATEGY_BREAK_BEFORE_MAKE"
				},
				{
					"service_name": "service-b",
					"environment_name": "production",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "default",
					"burst_strategy": "BURST_STRATEGY_DEFAULT"
				}
			]}`,
			expectedServices: []Service{
				{Name: "service-a", Tier: 1, GitURI: "gitolite@example.internal:go-code", HasOvercommit: true, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_ALL_ENVIRONMENTS", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_NO_ENVIRONMENT"},
				{Name: "service-b", Tier: 2, GitURI: "gitolite@example.internal:go-code", HasOvercommit: false, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_ALL_ENVIRONMENTS", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_NO_ENVIRONMENT"},
				{Name: "cff-demo", Tier: -1, HasOvercommit: false, BreakBeforeMakeBurstStrategy: "", MakeBeforeBreakBurstStrategy: ""},
			},
			expectNamespaceError: false,
		},
		{
			name: "enrichment with make-before-break",
			servicesResponse: `{"result": [
				{"name": "service-c", "tier": 3, "git_uri": "gitolite@example.internal:go-code"}
			]}`,
			namespaceResponse: `{"result": [
				{
					"service_name": "service-c",
					"environment_name": "production",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_MAKE_BEFORE_BREAK"
				}
			]}`,
			expectedServices: []Service{
				{Name: "service-c", Tier: 3, GitURI: "gitolite@example.internal:go-code", HasOvercommit: true, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_NO_ENVIRONMENT", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_ALL_ENVIRONMENTS"},
				{Name: "cff-demo", Tier: -1, HasOvercommit: false, BreakBeforeMakeBurstStrategy: "", MakeBeforeBreakBurstStrategy: ""},
			},
			expectNamespaceError: false,
		},
		{
			name: "enrichment fails but returns non-enriched services",
			servicesResponse: `{"result": [
				{"name": "service-a", "tier": 1, "git_uri": "gitolite@example.internal:go-code"}
			]}`,
			namespaceResponse: "",
			expectedServices: []Service{
				{Name: "service-a", Tier: 1, GitURI: "gitolite@example.internal:go-code", HasOvercommit: false, BreakBeforeMakeBurstStrategy: "", MakeBeforeBreakBurstStrategy: ""},
				{Name: "cff-demo", Tier: -1, HasOvercommit: false, BreakBeforeMakeBurstStrategy: "", MakeBeforeBreakBurstStrategy: ""},
			},
			expectNamespaceError: true,
		},
		{
			name: "mixed burst strategies across environments",
			servicesResponse: `{"result": [
				{"name": "service-mixed", "tier": 2, "git_uri": "gitolite@example.internal:go-code"}
			]}`,
			namespaceResponse: `{"result": [
				{
					"service_name": "service-mixed",
					"environment_name": "production",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_BREAK_BEFORE_MAKE"
				},
				{
					"service_name": "service-mixed",
					"environment_name": "prod-2",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_MAKE_BEFORE_BREAK"
				},
				{
					"service_name": "service-mixed",
					"environment_name": "canary",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_BREAK_BEFORE_MAKE"
				}
			]}`,
			expectedServices: []Service{
				{Name: "service-mixed", Tier: 2, GitURI: "gitolite@example.internal:go-code", HasOvercommit: true, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_SOME_ENVIRONMENTS", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_SOME_ENVIRONMENTS"},
				{Name: "cff-demo", Tier: -1, HasOvercommit: false, BreakBeforeMakeBurstStrategy: "", MakeBeforeBreakBurstStrategy: ""},
			},
			expectNamespaceError: false,
		},
		{
			name: "all make-before-break across multiple environments",
			servicesResponse: `{"result": [
				{"name": "service-all-mbb", "tier": 1, "git_uri": "gitolite@example.internal:go-code"}
			]}`,
			namespaceResponse: `{"result": [
				{
					"service_name": "service-all-mbb",
					"environment_name": "production",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_MAKE_BEFORE_BREAK"
				},
				{
					"service_name": "service-all-mbb",
					"environment_name": "prod-staging",
					"environment_type": "ENVIRONMENT_TYPE_PROD",
					"namespace": "overcommit",
					"burst_strategy": "BURST_STRATEGY_MAKE_BEFORE_BREAK"
				}
			]}`,
			expectedServices: []Service{
				{Name: "service-all-mbb", Tier: 1, GitURI: "gitolite@example.internal:go-code", HasOvercommit: true, BreakBeforeMakeBurstStrategy: "BURST_STRATEGY_BREAK_BEFORE_MAKE_NO_ENVIRONMENT", MakeBeforeBreakBurstStrategy: "BURST_STRATEGY_MAKE_BEFORE_BREAK_ALL_ENVIRONMENTS"},
				{Name: "cff-demo", Tier: -1, HasOvercommit: false, BreakBeforeMakeBurstStrategy: "", MakeBeforeBreakBurstStrategy: ""},
			},
			expectNamespaceError: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			callCount := 0
			ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				require.Equal(t, http.MethodPost, r.Method)
				w.Header().Set("Content-Type", "application/json")

				if callCount == 0 {
					// First call is for AllServices
					w.WriteHeader(http.StatusOK)
					_, err := w.Write([]byte(tt.servicesResponse))
					require.NoError(t, err)
				} else {
					// Second call is for namespace/burst_strategy enrichment
					if tt.expectNamespaceError {
						w.WriteHeader(http.StatusInternalServerError)
					} else {
						w.WriteHeader(http.StatusOK)
						_, err := w.Write([]byte(tt.namespaceResponse))
						require.NoError(t, err)
					}
				}
				callCount++
			}))
			defer ts.Close()

			grail, err := New(&Options{Host: ts.URL, USSOToken: "xxxx"})
			require.NoError(t, err)

			services, err := grail.AllServices(context.Background())
			require.NoError(t, err)
			require.Equal(t, tt.expectedServices, services)
		})
	}
}
